class Solution {public long solve(int[][] costs){int n=costs.length;if(n<2)return 0;int size=1<<n;long inf=Long.MAX_VALUE/4;long[][] d=new long[size][n];for(long[] row:d)Arrays.fill(row,inf);d[1][0]=0;for(int mask=1;mask<size;mask+=2)for(int a=0;a<n;a++)if(d[mask][a]<inf)for(int b=1;b<n;b++)if((mask&(1<<b))==0)d[mask|(1<<b)][b]=Math.min(d[mask|(1<<b)][b],d[mask][a]+costs[a][b]);long best=inf;for(int last=1;last<n;last++)best=Math.min(best,d[size-1][last]+costs[last][0]);return best;}}